exports.reconcileLedger = function(opening, entries) {
  // Validate input types
  if (typeof opening !== 'number' || !Number.isInteger(opening)) {
    throw new Error('Opening balance must be an integer');
  }
  if (typeof entries !== 'object' || entries === null) {
    throw new Error('Entries must be an object');
  }

  // Validate opening balance
  if (opening < 0) {
    throw new Error('Opening balance must be non-negative');
  }

  // Validate entries array
  if (!Array.isArray(entries)) {
    throw new Error('Entries must be an array');
  }

  // Validate each entry
  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];
    if (typeof entry !== 'object' || entry === null || entry === undefined) {
      throw new Error(`Entry at index ${i} must be an object`);
    }

    const [id, kind, amount] = entry;

    // Validate id
    if (typeof id !== 'string' || id.trim() === '') {
      throw new Error(`Entry at index ${i} must have a non-empty unique id`);
    }

    // Validate kind
    if (typeof kind !== 'number') {
      throw new Error(`Entry at index ${i} kind must be a number`);
    }
    if (kind !== 1 && kind !== -1) {
      throw new Error(`Entry at index ${i} kind must be 1 (credit) or -1 (debit)`);
    }

    // Validate amount
    if (typeof amount !== 'number' || amount <= 0) {
      throw new Error(`Entry at index ${i} amount must be a positive number`);
    }
  }

  // Check for duplicate ids
  const idMap = new Map();
  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];
    const [id, kind, amount] = entry;
    if (idMap.has(id)) {
      throw new Error(`Duplicate id ${id} found in entries`);
    }
    idMap.set(id, { kind, amount });
  }

  // Perform reconciliation
  let currentBalance = opening;
  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];
    const [id, kind, amount] = entry;
    currentBalance += amount * kind;
  }

  return currentBalance;
};

